TOOL = '<div class="tool" id="vc-tool">\n  <div class="card">\n    <div class="scan-drop" id="vc-drop">\n      <p style="margin:0 0 12px"><b>Drop a video here</b> or choose a file</p>\n      <button type="button" class="btn primary" id="vc-pick">Choose video</button>\n      <input type="file" id="vc-file" accept="video/*,.mkv,.mov,.mp4,.webm" hidden>\n      <p class="help">MP4, MOV, MKV or WebM. Large files are fine. Best in Chrome or Edge on a computer.</p>\n    </div>\n\n    <div id="vc-controls" hidden>\n      <div class="vc-file"><div class="ico"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="2" y="5" width="14" height="14" rx="2"/><path d="m16 10 6-3v10l-6-3z"/></svg></div><div><b id="vc-name"></b><small id="vc-meta"></small></div></div>\n\n      <div class="field" style="margin-top:18px"><label>How small should it be?</label>\n        <div class="vc-presets" id="vc-presets">\n          <button type="button" aria-pressed="false" data-frac="0.125"><b>Smallest</b><small></small></button>\n          <button type="button" aria-pressed="true" data-frac="0.25"><b>Balanced</b><small></small></button>\n          <button type="button" aria-pressed="false" data-frac="0.45"><b>Best quality</b><small></small></button>\n        </div>\n      </div>\n      <div class="field"><label for="vc-target">Or set an exact size: <b id="vc-target-v"></b></label><input type="range" id="vc-target" min="50" max="1500" step="10" value="500"><p class="help" id="vc-quality"></p></div>\n\n      <div class="row2">\n        <div class="field"><label for="vc-res">Resolution</label><select id="vc-res"></select></div>\n        <div class="field"><label for="vc-fmt">Format</label><select id="vc-fmt"><option value="mp4">MP4 (works everywhere)</option><option value="webm">WebM</option></select></div>\n      </div>\n\n      <div class="field" style="margin-top:6px"><label>Trim or cut into two parts</label>\n        <div class="vc-time" id="vc-time"><div class="vc-sel" id="vc-sel"><i id="vc-h-start" aria-label="Trim start"></i><i id="vc-h-end" aria-label="Trim end"></i></div><div class="vc-cut" id="vc-cut" hidden></div></div>\n        <div class="vc-times"><span id="vc-t-start">Start 0:00</span><span id="vc-len"></span><span id="vc-t-end"></span></div>\n        <div class="vc-clip"><button type="button" class="btn" id="vc-set-start">Set start here</button><button type="button" class="btn" id="vc-set-end">Set end here</button></div>\n        <div class="vc-switch"><span><b>Cut into two parts</b><br><small class="help" style="margin:0">Each part is compressed on its own, handy for upload limits.</small></span><input type="checkbox" id="vc-split" aria-label="Cut into two parts"></div>\n        <div class="field" id="vc-split-pos" hidden><label for="vc-cutrange">Split at <b id="vc-cut-v"></b></label><input type="range" id="vc-cutrange" min="0" max="100" value="50" step="0.1"></div>\n      </div>\n\n      <div class="btns" style="margin-top:14px"><button type="button" class="btn primary" id="vc-go">Compress video</button><button type="button" class="btn" id="vc-reset">Choose another</button></div>\n    </div>\n    <p class="help" id="vc-status" role="status"></p>\n  </div>\n\n  <div class="card preview" aria-live="polite">\n    <div class="vc-stage" id="vc-stage" hidden><video id="vc-video" controls playsinline preload="metadata"></video></div>\n    <div class="vc-rstage" id="vc-rstage" hidden><video id="vc-result-preview" controls playsinline></video></div>\n    <p class="help" id="vc-empty" style="text-align:center;margin-top:12px">Your video preview appears here</p>\n    <span id="vc-tc" hidden></span>\n\n    <div id="vc-progress" hidden style="margin-top:16px"><b id="vc-pl">Compressing... 0%</b> <span class="help" id="vc-pt"></span><div class="vc-bar"><span id="vc-pb"></span></div><p class="help">Keep this tab open. Everything runs on your device.</p><div class="btns"><button type="button" class="btn" id="vc-stop">Stop</button></div></div>\n\n    <div id="vc-result" hidden style="margin-top:16px">\n      <div class="vc-res"><div><small>Before</small><b id="vc-before"></b></div><span class="save" id="vc-save"></span><div><small>After</small><b id="vc-after"></b></div></div>\n      <div class="vc-parts" id="vc-parts"></div>\n      <div class="btns" style="margin-top:12px"><button type="button" class="btn" id="vc-again">Compress another</button></div>\n    </div>\n  </div>\n</div>'

SECTIONS = '<section class="block prose"><h2>How to compress a video</h2>\n<ol>\n<li><b>Add your video.</b> Drop it on the box or choose a file.</li>\n<li><b>Pick a size.</b> Choose Smallest, Balanced or Best quality, or set the exact size you need.</li>\n<li><b>Trim or split (optional).</b> Drag the handles to cut off the start and end, or turn on Cut into two parts and move the split marker.</li>\n<li><b>Compress and download.</b> It takes a few minutes. Then save your video, or both parts.</li>\n</ol></section>\n<section class="block prose"><h2>How to get a 2 GB video down to 500 MB</h2>\n<p>Pick Balanced, which aims for about a quarter of the original size, or drag the size slider to the exact number you need. For a smaller file with a sharper picture, also lower the resolution to 720p. A phone or laptop screen rarely shows the difference.</p></section>\n<section class="block prose"><h2>Cut a video into two parts</h2>\n<p>Some sites and chat apps limit upload size. Turn on <b>Cut into two parts</b>, set the split point, and the tool creates two separate videos, each compressed to share the size you chose.</p></section>\n<section class="block prose"><h2>Tips for the best result</h2>\n<ul>\n<li>Use Chrome or Edge on a computer. Phones and older browsers are not supported.</li>\n<li>Keep the tab open and let your computer stay awake while it works.</li>\n<li>Choose MP4 unless you know you need WebM. MP4 plays on almost every device.</li>\n<li>If the result looks soft, raise the size a little or lower the resolution.</li>\n</ul></section>'

